@verbatim
<!DOCTYPE html>
<html lang="id">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<title>Samudra Detailing – Auto Detailing &amp; Ceramic Coating</title>
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Unbounded:wght@400;700;900&family=Figtree:wght@400;500;700&display=swap">
<style>
:root{--bg:#EAF6FF;--ink:#031B34;--card:#fff;--line:#031B3426;--ocean:#0A6EBD;--cyan:#16B8D6;--aqua:#8FF0D8;--coral:#FF6B57;--mute:#031B34b3;--d:'Unbounded','Arial Black',sans-serif;--b:'Figtree','Segoe UI',Arial,sans-serif;box-sizing:border-box;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]){--bg:#031B34;--ink:#EAF8FF;--card:#06335E;--line:#EAF8FF2e;--cyan:#38D6E8;--mute:#EAF8FFb3}}
:root[data-theme="dark"]{--bg:#031B34;--ink:#EAF8FF;--card:#06335E;--line:#EAF8FF2e;--cyan:#38D6E8;--mute:#EAF8FFb3}
html{scroll-behavior:smooth}*{box-sizing:border-box;margin:0}
body{background:var(--bg);color:var(--ink);font:400 17px/1.65 var(--b);overflow-x:hidden}
a{color:inherit;text-decoration:none}button{font:inherit;color:inherit}
header.top{position:sticky;top:0;z-index:70;background:color-mix(in srgb,var(--bg) 94%,transparent);border-bottom:1px solid var(--line);padding-top:env(safe-area-inset-top,0px)}
header.top::before{content:"";position:absolute;inset:0;z-index:0;backdrop-filter:blur(14px);pointer-events:none}
.bar{position:relative;z-index:1;display:flex;align-items:center;justify-content:space-between;padding:14px 4vw;gap:18px}
.brand{font:900 20px var(--d);letter-spacing:-.04em;display:flex;align-items:center;gap:10px}
.brand i{width:22px;height:28px;background:linear-gradient(160deg,var(--aqua),var(--ocean));border-radius:50% 50% 50% 50%/62% 62% 38% 38%;transform:rotate(180deg)}
#menu{display:flex;gap:24px;font-size:14px;font-weight:700}
#menu a{padding:4px 0;border-bottom:3px solid transparent;transition:.2s}#menu a:hover{color:var(--cyan)}#menu a.on{border-color:var(--cyan)}
.btn{display:inline-block;background:var(--coral);color:#fff;border:0;border-radius:60px;padding:13px 28px;font:700 15px var(--b);cursor:pointer;transition:transform .25s,box-shadow .25s}
.btn:hover{transform:translateY(-3px);box-shadow:0 12px 24px -8px var(--coral)}
.btn.o{background:none;color:var(--ink);border:2px solid var(--ink)}.btn.o:hover{box-shadow:none;background:var(--ink);color:var(--bg)}
#burger{display:none;background:none;border:2px solid var(--ink);border-radius:30px;padding:6px 16px;font-weight:700;cursor:pointer}
.pg{display:none}.pg.on{display:block;animation:rise .7s cubic-bezier(.2,.8,.2,1)}
@keyframes rise{from{opacity:0;transform:translateY(30px)}}
.wrap{padding:70px 4vw 110px;max-width:1300px;margin:auto}
.kick{font:700 12px var(--b);letter-spacing:.24em;text-transform:uppercase;color:var(--cyan)}
h1,h2{font-family:var(--d);font-weight:900;letter-spacing:-.045em;line-height:1}
.ph{font-size:clamp(40px,7vw,100px);margin:10px 0 40px}
.hero{position:relative;overflow:hidden;background:linear-gradient(180deg,#031B34,#06335E 70%,#0A6EBD);color:#EAF8FF;padding:80px 4vw 190px}
.hero .in{display:grid;grid-template-columns:1.05fr .95fr;gap:4vw;align-items:center;max-width:1300px;margin:auto;position:relative;z-index:2}
.hero h1{font-size:clamp(44px,7.4vw,110px);margin:14px 0 22px}.hero h1 em{font-style:normal;color:var(--aqua);display:block}
.hero p{max-width:42ch;font-size:19px;opacity:.9}.hero .btns{display:flex;gap:14px;flex-wrap:wrap;margin-top:30px}.hero .btn.o{color:#EAF8FF;border-color:#EAF8FF}.hero .btn.o:hover{background:#EAF8FF;color:#031B34}
.hood{--mx:50%;--my:50%;position:relative;aspect-ratio:1/1.02;border-radius:40px 150px 40px 150px;overflow:hidden;border:2px solid #8FF0D866;touch-action:none;cursor:none;box-shadow:0 40px 80px -30px #000}
.dull,.gloss{position:absolute;inset:0}
.dull{background:repeating-radial-gradient(circle at 22% 30%,#ffffff14 0 1px,transparent 1px 7px),repeating-linear-gradient(115deg,#ffffff16 0 1px,transparent 1px 12px),repeating-linear-gradient(35deg,#0000001c 0 1px,transparent 1px 9px),radial-gradient(circle at 30% 20%,#8798ab,#4d5d70 60%,#37424f)}
.gloss{background:radial-gradient(circle at 18% 22%,#fff9 0 3px,#8fe9ff55 4px 8px,transparent 9px),radial-gradient(circle at 70% 34%,#fffa 0 4px,#8fe9ff55 5px 10px,transparent 11px),radial-gradient(circle at 44% 70%,#fff9 0 3px,#8fe9ff55 4px 8px,transparent 9px),radial-gradient(circle at 82% 78%,#fffa 0 5px,#8fe9ff55 6px 12px,transparent 13px),radial-gradient(circle at 28% 52%,#fff8 0 2px,#8fe9ff44 3px 6px,transparent 7px),linear-gradient(100deg,transparent 28%,#ffffff66 36%,transparent 46%),linear-gradient(180deg,#0A6EBD,#0b4f94 44%,#02122a 47%,#03315f 50%,#0A8FD8 100%);-webkit-mask:radial-gradient(circle 150px at var(--mx) var(--my),#000 55%,transparent 100%);mask:radial-gradient(circle 150px at var(--mx) var(--my),#000 55%,transparent 100%)}
.hood span{position:absolute;bottom:22px;font:700 12px var(--b);letter-spacing:.22em;text-transform:uppercase;background:#031B34cc;padding:6px 14px;border-radius:20px}
.hood span:first-of-type{left:26px}.hood span:last-of-type{right:26px;color:var(--aqua)}
.hood .hint{position:absolute;left:50%;top:18px;transform:translateX(-50%);background:var(--coral);color:#fff;padding:6px 14px;font:700 12px var(--b);border-radius:20px;letter-spacing:.1em;white-space:nowrap}
.wave{position:absolute;left:0;bottom:-1px;width:100%;height:150px;overflow:hidden;z-index:1}
.wave svg{position:absolute;bottom:0;width:200%;height:100%;animation:wv 14s linear infinite}
.wave svg:nth-child(2){animation-duration:9s;animation-direction:reverse;opacity:.55;height:80%}
.wave svg:nth-child(1) path{fill:var(--bg)}.wave svg:nth-child(2) path{fill:#38D6E8}
@keyframes wv{to{transform:translateX(-50%)}}
.bub{position:absolute;bottom:-40px;border-radius:50%;border:2px solid #8FF0D888;background:radial-gradient(circle at 30% 30%,#fff6,transparent 60%);animation:up linear infinite;z-index:1}
@keyframes up{to{transform:translateY(-120vh) translateX(30px)}}
.tick{background:var(--coral);color:#fff;overflow:hidden;white-space:nowrap;padding:12px 0}
.tick span{display:inline-block;font:700 14px var(--d);letter-spacing:.14em;text-transform:uppercase;animation:mq 30s linear infinite}
@keyframes mq{to{transform:translateX(-50%)}}
.g3{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:26px}
.card{background:var(--card);border:1px solid var(--line);border-radius:30px 90px 30px 30px;padding:30px;position:relative;overflow:hidden;transition:transform .4s}
.card:hover{transform:translateY(-8px)}
.card::after{content:"";position:absolute;right:-40px;bottom:-40px;width:140px;height:140px;border-radius:50%;border:2px solid var(--cyan);opacity:0;transition:.6s;box-shadow:0 0 0 18px #16B8D61a,0 0 0 40px #16B8D610}
.card:hover::after{opacity:1;right:-10px;bottom:-10px}
.card .no{font:900 54px/1 var(--d);color:var(--cyan);opacity:.9}.card h3{font:700 22px/1.15 var(--d);letter-spacing:-.03em;margin:14px 0 8px}.card p{color:var(--mute);font-size:15.5px}
.steps{display:flex;gap:0;flex-wrap:wrap;margin-top:60px}
.steps div{flex:1 1 220px;padding:26px 24px;border-left:2px dashed var(--cyan);position:relative}
.steps div::before{content:"";position:absolute;left:-8px;top:0;width:14px;height:14px;border-radius:50%;background:var(--coral)}
.steps b{font:700 18px var(--d);display:block;margin-bottom:6px}.steps p{color:var(--mute);font-size:15px}
.zs{display:flex;gap:10px;margin:0 0 36px;flex-wrap:wrap}
.zs button{border:2px solid var(--ink);background:none;border-radius:40px;padding:9px 22px;font-weight:700;cursor:pointer}
.zs button.on{background:var(--ink);color:var(--bg)}
.plan{display:flex;flex-direction:column}.plan.f{background:linear-gradient(170deg,#0A6EBD,#031B34);color:#EAF8FF;border:0}.plan.f p,.plan.f li{color:#EAF8FFcc}
.plan ul{list-style:none;padding:0;margin:14px 0 24px;display:grid;gap:8px;flex:1;font-size:15px}.plan li::before{content:"✦ ";color:var(--cyan)}
.plan .pr{font:900 30px var(--d);letter-spacing:-.04em}.plan small{display:block;color:var(--mute);margin-bottom:16px}
.ba{--p:50%;position:relative;aspect-ratio:4/3;border-radius:28px;overflow:hidden;border:1px solid var(--line)}
.ba .l{position:absolute;inset:0;display:grid;place-items:end start;padding:18px;font:700 12px var(--b);letter-spacing:.2em;text-transform:uppercase;color:#fff}
.ba .l.b{background:var(--gb)}.ba .l.a{background:var(--ga);clip-path:inset(0 calc(100% - var(--p)) 0 0)}
.ba .l.a em{font-style:normal;color:var(--aqua)}
.ba input{position:absolute;inset:0;width:100%;height:100%;opacity:0;cursor:ew-resize;margin:0}
.ba .hd{position:absolute;top:0;bottom:0;left:var(--p);width:4px;background:#fff;pointer-events:none;box-shadow:0 0 14px #0008}
.ba .hd::after{content:"⇄";position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);width:44px;height:44px;background:var(--coral);color:#fff;border-radius:50%;display:grid;place-items:center;font-size:20px}
.cap{margin:12px 6px 0;font-weight:700}.cap small{display:block;font-weight:400;color:var(--mute)}
.two{display:grid;grid-template-columns:1fr 1fr;gap:5vw;align-items:start}
.stats{display:flex;gap:4vw;flex-wrap:wrap;margin:40px 0;border-block:1px solid var(--line);padding:26px 0}
.stats div{flex:1 1 140px}.stats b{display:block;font:900 clamp(40px,5vw,70px)/1 var(--d);letter-spacing:-.05em;color:var(--cyan)}.stats span{font-size:13px;font-weight:700;letter-spacing:.14em;text-transform:uppercase}
.form{display:grid;grid-template-columns:1fr 1fr;gap:22px}
.form label{font:700 12px var(--b);letter-spacing:.18em;text-transform:uppercase}.form .f{grid-column:1/-1}
.form input,.form select{width:100%;margin-top:6px;border:0;border-bottom:2px solid var(--ink);background:transparent;padding:10px 0;font:400 18px var(--b);color:var(--ink);border-radius:0}
.form select option{color:#031B34}
.info{background:linear-gradient(170deg,#0A6EBD,#031B34);color:#EAF8FF;padding:34px;border-radius:30px 100px 30px 30px}.info h3{font:900 28px var(--d);letter-spacing:-.04em;margin-bottom:10px}.info p{margin-top:10px;opacity:.9}
footer{border-top:1px solid var(--line);padding:26px 4vw 110px;display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap;font-size:13px;color:var(--mute)}
#bot{position:fixed;right:16px;bottom:calc(16px + env(safe-area-inset-bottom,0px));z-index:100}
#fab{width:72px;height:72px;border:0;cursor:pointer;background:linear-gradient(160deg,var(--aqua),var(--ocean));border-radius:50% 50% 50% 50%/62% 62% 38% 38%;transform:rotate(180deg);box-shadow:0 12px 30px -8px #0A6EBD;animation:bob 3s ease-in-out infinite}
#fab::after{content:"";position:absolute;inset:0;transform:rotate(180deg);background:radial-gradient(circle at 36% 34%,#fffa 0 6px,transparent 7px)}
@keyframes bob{50%{transform:rotate(180deg) translateY(8px)}}
#box{display:none;position:absolute;right:0;bottom:88px;width:min(370px,calc(100vw - 32px));height:min(540px,72vh);background:var(--bg);color:var(--ink);border:1px solid var(--line);border-radius:28px 28px 8px 28px;box-shadow:0 30px 70px -20px #000a;flex-direction:column;overflow:hidden}
#box.on{display:flex}
.hh{background:linear-gradient(120deg,#0A6EBD,#031B34);color:#EAF8FF;padding:16px 20px;display:flex;justify-content:space-between;align-items:center}
.hh b{font:700 16px var(--d);letter-spacing:-.03em}.hh a{background:#25D366;color:#053d1b;padding:5px 13px;border-radius:30px;font:700 12px var(--b)}
#log{flex:1;overflow:auto;padding:16px 18px;display:flex;flex-direction:column;gap:10px}
.m{max-width:88%;font-size:15px;line-height:1.5;white-space:pre-line;background:var(--card);border:1px solid var(--line);padding:9px 14px;border-radius:4px 18px 18px 18px}
.m.u{align-self:flex-end;background:var(--ocean);color:#fff;border-color:var(--ocean);border-radius:18px 4px 18px 18px}
.qc{display:flex;flex-wrap:wrap;gap:6px;padding:0 18px 10px}
.qc button{border:1px solid var(--cyan);background:none;border-radius:20px;padding:3px 13px;font:700 12.5px var(--b);cursor:pointer}.qc button:hover{background:var(--cyan);color:#031B34}
#f{display:flex;border-top:1px solid var(--line)}
#f input{flex:1;min-width:0;border:0;background:none;color:var(--ink);padding:15px 18px;font:16px var(--b)}#f input:focus{outline:0}
#f button{border:0;background:var(--coral);color:#fff;padding:0 22px;font:700 14px var(--b);cursor:pointer}
:focus-visible{outline:3px solid var(--coral);outline-offset:3px}
@media(max-width:960px){#burger{display:block}.nb{display:none}#menu{position:fixed;left:0;right:0;top:calc(60px + env(safe-area-inset-top,0px));bottom:0;height:calc(100dvh - 60px - env(safe-area-inset-top,0px));overflow-y:auto;background:var(--bg);flex-direction:column;gap:0;padding:20px 4vw;font:900 32px/1.5 var(--d);letter-spacing:-.04em;transform:translateY(-110%);visibility:hidden;opacity:0;pointer-events:none;transition:transform .5s cubic-bezier(.7,0,.2,1),visibility .5s,opacity .2s;z-index:65}#menu.open{transform:none;visibility:visible;opacity:1;pointer-events:auto}#menu a{border:0;border-bottom:1px solid var(--line)}.hero .in,.two{grid-template-columns:1fr}.form{grid-template-columns:1fr}.hero{padding-bottom:150px}}
@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}
</style>
</head>
<body>
<header class="top"><div class="bar">
  <a class="brand" href="#beranda"><i></i>Samudra</a>
  <nav id="menu" aria-label="Menu utama" aria-hidden="true"><a href="#beranda">Beranda</a><a href="#layanan">Layanan</a><a href="#paket">Paket</a><a href="#galeri">Galeri</a><a href="#tentang">Tentang</a><a href="#kontak">Kontak</a></nav>
  <a class="btn nb" href="#kontak">Booking</a><button id="burger" aria-expanded="false" aria-controls="menu">Menu</button>
</div></header>
<main>
<section class="pg" data-p="beranda">
  <div class="hero" id="hero"><div id="bubs"></div>
    <div class="in">
      <div><span class="kick" style="color:var(--aqua)">Auto detailing &amp; ceramic coating · Surabaya</span>
        <h1>Kilau sedalam <em>samudra.</em></h1>
        <p>Cat mobilmu bukan sekadar bersih. Kami memolesnya sampai memantulkan langit, lalu mengunci kilau itu bertahun-tahun.</p>
        <div class="btns"><a class="btn" href="#kontak">Booking sekarang</a><a class="btn o" href="#paket">Lihat paket</a></div></div>
      <div class="hood" id="hood" aria-label="Gosok untuk melihat efek poles"><div class="dull"></div><div class="gloss"></div><span>Kusam</span><span>Berkilau</span><b class="hint">Gosok panel ini ✦</b></div>
    </div>
    <div class="wave" aria-hidden="true"><svg viewBox="0 0 1200 120" preserveAspectRatio="none"><path d="M0 60C100 20 200 20 300 60S500 100 600 60 800 20 900 60s200 40 300 0V120H0Z"/></svg><svg viewBox="0 0 1200 120" preserveAspectRatio="none"><path d="M0 60C100 20 200 20 300 60S500 100 600 60 800 20 900 60s200 40 300 0V120H0Z"/></svg></div>
  </div>
  <div class="tick" aria-hidden="true"><span>Paint correction ✦ Ceramic coating ✦ Interior deep clean ✦ Headlight restoration ✦ Paint correction ✦ Ceramic coating ✦ Interior deep clean ✦ Headlight restoration ✦ </span></div>
  <div class="wrap"><span class="kick">Cara kami bekerja</span><h2 class="ph" style="font-size:clamp(34px,5vw,64px)">Empat arus menuju kilau.</h2>
    <div class="steps"><div><b>Cuci presisi</b><p>Pre-wash busa salju dan dua ember agar tidak ada goresan baru.</p></div><div><b>Dekontaminasi</b><p>Clay bar dan iron remover mengangkat kotoran yang tak terlihat.</p></div><div><b>Poles</b><p>Mesin poles menghapus swirl dan oksidasi sampai cat jernih.</p></div><div><b>Kunci</b><p>Wax atau ceramic coating melapisi cat agar air dan kotoran meluncur.</p></div></div></div>
</section>

<section class="pg" data-p="layanan"><div class="wrap"><span class="kick">Yang kami kerjakan</span><h1 class="ph">Layanan</h1><div class="g3" id="lay"></div></div></section>

<section class="pg" data-p="paket"><div class="wrap"><span class="kick">Transparan, tanpa biaya tersembunyi</span><h1 class="ph">Paket</h1>
  <div class="zs" id="zs" role="group" aria-label="Ukuran mobil"></div><div class="g3" id="pk"></div></div></section>

<section class="pg" data-p="galeri"><div class="wrap"><span class="kick">Geser untuk membandingkan</span><h1 class="ph">Galeri</h1><div class="g3" id="gl"></div></div></section>

<section class="pg" data-p="tentang"><div class="wrap"><span class="kick">Studio kami</span><h1 class="ph">Tentang</h1>
  <div class="two"><p style="font:700 clamp(22px,2.6vw,34px)/1.3 var(--d);letter-spacing:-.03em">Kami percaya setiap mobil punya cerita, dan cat yang bersih adalah bab pertamanya.</p>
  <div><p style="margin-bottom:16px">Samudra Detailing berdiri dari kecintaan pada mobil dan obsesi pada detail. Setiap mobil dikerjakan satu teknisi utama dari awal sampai akhir, dengan produk bersertifikat dan pencahayaan studio yang jujur memperlihatkan setiap cacat.</p><p>Kami tidak mengejar jumlah mobil. Kami mengejar hasil yang membuatmu berhenti sejenak setiap kali menoleh ke mobilmu di parkiran.</p></div></div>
  <div class="stats"><div><b>9</b><span>Tahun pengalaman</span></div><div><b>1.200+</b><span>Mobil dirawat</span></div><div><b>3 th</b><span>Garansi coating</span></div><div><b>4,9</b><span>Rating pelanggan</span></div></div></div></section>

<section class="pg" data-p="kontak"><div class="wrap"><span class="kick">Booking</span><h1 class="ph">Kontak</h1>
  <div class="two"><div class="form">
    <label class="f">Paket<select id="sv"></select></label>
    <label>Ukuran mobil<select id="zz"></select></label><label>Merek &amp; tipe mobil<input id="mk" placeholder="Contoh: Honda CR-V 2021"></label>
    <label>Tanggal<input type="date" id="dt"></label><label>Nama<input id="nm" placeholder="Nama lengkap"></label>
    <div class="f"><button class="btn" id="go" style="padding:16px 36px">Kirim ke WhatsApp</button></div></div>
  <div class="info"><h3>Studio Samudra</h3><p>Surabaya, Jawa Timur<br>Senin–Sabtu, 08.00–17.00 WIB<br>Instagram @samudra.detailing</p><p>Layanan antar-jemput tersedia untuk area Surabaya dan Sidoarjo.</p></div></div></div></section>
</main>
<footer><span>© 2026 Samudra Detailing</span></footer>

<div id="bot"><div id="box" role="dialog" aria-label="Chat Samudra">
  <div class="hh"><b>Asisten Samudra</b><a href="#" id="toWA">Lanjut ke WA</a></div>
  <div id="log"></div><div class="qc" id="chips"></div>
  <form id="f"><input id="in" placeholder="Tanya paket, harga, jadwal..." autocomplete="off" aria-label="Pesan"><button>Kirim</button></form></div>
  <button id="fab" aria-label="Buka chat"></button></div>

<script>
/* ===== CONFIG ===== */
const WA="6281234567890"; // format 62..., tanpa + atau 0
const P=[
 {id:"wash",n:"Wash & Wax",p:350000,t:"3 jam",f:["Cuci busa salju","Dekontaminasi ringan","Wax pelindung 1 bulan","Semir ban dan kaca"]},
 {id:"full",n:"Full Detailing",p:1800000,t:"1–2 hari",f:["Interior deep clean","Poles satu tahap","Clay bar dan iron remover","Wax sintetis 6 bulan"],hot:1},
 {id:"ceramic",n:"Ceramic Coating",p:4500000,t:"3 hari",f:["Paint correction 2 tahap","Ceramic coating 9H","Garansi 3 tahun","Gratis maintenance wash 3×"]}];
const Z=[{n:"Compact",f:1},{n:"Sedan",f:1.2},{n:"SUV / MPV",f:1.5}];
const L=[["Exterior Detailing","Cuci presisi, dekontaminasi, dan wax untuk cat yang halus dan terlindungi."],["Interior Deep Clean","Vakum, steam, dan perawatan jok kulit atau kain sampai bebas bau."],["Paint Correction","Hapus swirl, goresan halus, dan oksidasi dengan poles bertahap."],["Ceramic Coating","Lapisan keras 9H yang membuat air dan kotoran meluncur dari cat."],["Headlight Restoration","Lampu kuning dan buram jadi jernih lagi, malam hari lebih aman."],["Engine Bay Clean","Ruang mesin bersih dan rapi tanpa merusak kelistrikan."]];
const G=[["Paint Correction","Sedan hitam · swirl dalam","linear-gradient(135deg,#8a97a6,#4a5663)","linear-gradient(135deg,#0A6EBD,#02122a)"],["Headlight Restoration","SUV putih · lampu menguning","linear-gradient(135deg,#b9a56a,#6a5a2c)","linear-gradient(135deg,#d6f6ff,#38D6E8)"],["Interior Deep Clean","MPV abu-abu · noda jok","linear-gradient(135deg,#7b6a58,#3d3228)","linear-gradient(135deg,#c9b79b,#6a4f34)"]];
const rp=n=>"Rp"+n.toLocaleString("id-ID"),$=s=>document.querySelector(s);
const wa=t=>"https://wa.me/"+WA+"?text="+encodeURIComponent(t);
let zi=1;const price=p=>Math.round(p.p*Z[zi].f/10000)*10000;
/* router */
const PGS=[...document.querySelectorAll(".pg")].map(p=>p.dataset.p);
function route(){const h=(location.hash||"#beranda").slice(1),id=PGS.includes(h)?h:"beranda";
 document.querySelectorAll(".pg").forEach(p=>p.classList.toggle("on",p.dataset.p==id));
 document.querySelectorAll("#menu a").forEach(a=>a.classList.toggle("on",a.getAttribute("href")=="#"+id));
 $("#menu").classList.remove("open");$("#menu").setAttribute("aria-hidden","true");$("#burger").setAttribute("aria-expanded","false");scrollTo(0,0)}
addEventListener("hashchange",route);route();
$("#burger").onclick=()=>{const menu=$("#menu"),open=menu.classList.toggle("open");$("#burger").setAttribute("aria-expanded",String(open));menu.setAttribute("aria-hidden",String(!open))};
$("#menu").onclick=e=>{if(e.target.closest("a")&&innerWidth<=960){$("#menu").classList.remove("open");$("#menu").setAttribute("aria-hidden","true");$("#burger").setAttribute("aria-expanded","false")}};
addEventListener("keydown",e=>{if(e.key==="Escape"){$("#menu").classList.remove("open");$("#menu").setAttribute("aria-hidden","true");$("#burger").setAttribute("aria-expanded","false")}});
const go=id=>{if(location.hash=="#"+id)route();else location.hash=id};
/* gelembung */
$("#bubs").replaceChildren(...Array.from({length:16},()=>{const bubble=document.createElement("i"),s=8+Math.random()*26;bubble.className="bub";bubble.style.left=Math.random()*100+"%";bubble.style.width=s+"px";bubble.style.height=s+"px";bubble.style.animationDuration=9+Math.random()*12+"s";bubble.style.animationDelay=-Math.random()*14+"s";return bubble;}));
/* efek poles */
const hood=$("#hood");let manual=false,t0=0;
function sweep(t){if(!manual){const x=50+38*Math.sin(t/900),y=50+30*Math.sin(t/620+1);hood.style.setProperty("--mx",x+"%");hood.style.setProperty("--my",y+"%");requestAnimationFrame(sweep)}}
requestAnimationFrame(sweep);
hood.addEventListener("pointermove",e=>{manual=true;hood.querySelector(".hint").style.display="none";const r=hood.getBoundingClientRect();hood.style.setProperty("--mx",(e.clientX-r.left)+"px");hood.style.setProperty("--my",(e.clientY-r.top)+"px")});
/* layanan, paket, galeri */
$("#lay").replaceChildren(...L.map((x,i)=>{const card=document.createElement("article");card.className="card";const no=document.createElement("div"),title=document.createElement("h3"),copy=document.createElement("p");no.className="no";no.textContent="0"+(i+1);title.textContent=x[0];copy.textContent=x[1];card.append(no,title,copy);return card;}));
$("#zs").replaceChildren(...Z.map((z,i)=>{const b=document.createElement("button");b.type="button";b.className=i==1?"on":"";b.dataset.z=i;b.textContent=z.n;return b;}));
function drawP(){$("#pk").replaceChildren(...P.map(p=>{const card=document.createElement("article");card.className="card plan"+(p.hot?" f":"");const kick=document.createElement("span"),title=document.createElement("h3"),list=document.createElement("ul"),pr=document.createElement("div"),small=document.createElement("small"),button=document.createElement("button");kick.className="kick";kick.style.color="var(--"+(p.hot?"aqua":"cyan")+")";kick.textContent=p.hot?"Paling populer":"Estimasi "+p.t;title.textContent=p.n;p.f.forEach(x=>{const li=document.createElement("li");li.textContent=x;list.appendChild(li)});pr.className="pr";pr.textContent=rp(price(p));small.textContent=Z[zi].n+" · "+p.t;button.className="btn";button.dataset.s=p.id;button.textContent="Pilih paket";card.append(kick,title,list,pr,small,button);return card;}));}
drawP();
$("#zs").onclick=e=>{const b=e.target.closest("button");if(!b)return;zi=+b.dataset.z;document.querySelectorAll("#zs button").forEach(x=>x.classList.toggle("on",x==b));$("#zz").value=zi;drawP()};
$("#pk").onclick=e=>{const b=e.target.closest("[data-s]");if(b){$("#sv").value=b.dataset.s;go("kontak")}};
$("#gl").replaceChildren(...G.map(g=>{const item=document.createElement("div"),ba=document.createElement("div"),before=document.createElement("div"),after=document.createElement("div"),em=document.createElement("em"),handle=document.createElement("div"),range=document.createElement("input"),cap=document.createElement("div"),small=document.createElement("small");ba.className="ba";ba.style.setProperty("--gb",g[2]);ba.style.setProperty("--ga",g[3]);before.className="l b";before.textContent="Sebelum";after.className="l a";em.textContent="Sesudah";after.appendChild(em);handle.className="hd";range.type="range";range.min="2";range.max="98";range.value="50";range.setAttribute("aria-label","Geser perbandingan "+g[0]);ba.append(before,after,handle,range);cap.className="cap";cap.append(document.createTextNode(g[0]),small);small.textContent=g[1];item.append(ba,cap);return item;}));
$("#gl").oninput=e=>{if(e.target.type=="range")e.target.parentNode.style.setProperty("--p",e.target.value+"%")};
/* booking */
$("#sv").replaceChildren(...P.map(p=>{const o=document.createElement("option");o.value=p.id;o.textContent=p.n;return o;}));$("#zz").replaceChildren(...Z.map((z,i)=>{const o=document.createElement("option");o.value=i;o.textContent=z.n;return o;}));$("#zz").value=1;
$("#zz").onchange=e=>{zi=+e.target.value;document.querySelectorAll("#zs button").forEach((x,i)=>x.classList.toggle("on",i==zi));drawP()};
const sv=()=>P.find(x=>x.id==$("#sv").value);
$("#go").onclick=()=>{const d=$("#dt").value,s=sv();window.open(wa("Halo Samudra Detailing, saya mau booking.\nPaket: "+s.n+" ("+rp(price(s))+" untuk "+Z[zi].n+")\nMobil: "+($("#mk").value||"-")+"\nTanggal: "+(d?new Date(d).toLocaleDateString("id-ID",{day:"numeric",month:"long",year:"numeric"}):"belum pasti")+"\nNama: "+($("#nm").value||"-")+"\nApakah jadwal tersebut tersedia?"),"_blank","noopener,noreferrer")};
/* ===== Chatbot ===== */
const box=$("#box"),log=$("#log"),inp=$("#in"),hist=[];let hi=false;
const KB=[
 [/paket|layanan|jasa|menu/,()=>"Paket kami:\n"+P.map(x=>"• "+x.n+" "+rp(price(x))+" ("+Z[zi].n+")").join("\n")+"\nKetik “saya mau ceramic” untuk memilihnya."],
 [/harga|biaya|tarif|berapa/,()=>"Harga untuk "+Z[zi].n+":\n"+P.map(x=>x.n+": "+rp(price(x))).join("\n")+"\nSedan +20%, SUV/MPV +50% dari harga compact."],
 [/lama|durasi|berapa hari|selesai/,()=>P.map(x=>x.n+": "+x.t).join("\n")],
 [/garansi|tahan|awet|coating/,()=>"Ceramic coating 9H bergaransi 3 tahun dengan syarat maintenance wash berkala. Gratis 3× maintenance wash di paket Ceramic."],
 [/antar|jemput|pickup|area|lokasi|alamat/,()=>"Studio kami di Surabaya. Antar-jemput tersedia untuk Surabaya dan Sidoarjo, biaya sesuai jarak."],
 [/dp|bayar|pembayaran|booking/,()=>"Booking cukup DP 30%, pelunasan saat mobil diambil. Isi form Kontak atau tekan “Lanjut ke WA”."],
 [/interior|jok|bau/,()=>"Interior Deep Clean memakai steam dan vakum, aman untuk kulit dan kain, bau rokok dan apek hilang."],
 [/galeri|hasil|before|sebelum/,()=>{go("galeri");return"Kubuka halaman Galeri, geser slider untuk melihat sebelum dan sesudah."}],
 [/tentang|siapa/,()=>{go("tentang");return"Kubuka halaman Tentang."}],
 [/kontak|hubungi/,()=>{go("kontak");return"Kubuka halaman Kontak dengan form booking."}],
 [/halo|hai|hi\b|pagi|siang|malam/,()=>"Halo! Mobil apa yang mau kita buat berkilau hari ini?"]
];
function add(t,u){const d=document.createElement("div");d.className="m"+(u?" u":"");d.textContent=t;log.appendChild(d);log.scrollTop=log.scrollHeight}
function ask(t){if(!t.trim())return;add(t,1);hist.push("Saya: "+t);const l=t.toLowerCase();let a;
 const it=P.find(x=>l.includes(x.id)||l.includes(x.n.split(" ")[0].toLowerCase()));
 if(it&&/mau|ingin|pilih|booking|pesan/.test(l)){$("#sv").value=it.id;go("kontak");a=it.n+" sudah dipilih dan form Kontak kubuka. Lengkapi data mobil dan tanggal, atau tekan “Lanjut ke WA”."}
 else if(it)a=it.n+" ("+it.t+"): "+it.f.join(", ")+". "+rp(price(it))+" untuk "+Z[zi].n+"."
 else{const k=KB.find(([r])=>r.test(l));a=k?k[1]():"Pertanyaan itu paling pas dijawab tim kami langsung. Tekan “Lanjut ke WA” di atas ya."}
 setTimeout(()=>{add(a);hist.push("Asisten: "+a)},450)}
$("#fab").onclick=()=>{if(box.classList.toggle("on")&&!hi){hi=true;add("Halo! Aku asisten Samudra. Aku bisa bantu soal paket, harga, durasi, garansi, atau langsung booking.");$("#chips").replaceChildren(...["Lihat paket","Harga","Garansi coating","Antar jemput","Galeri"].map(c=>{const b=document.createElement("button");b.type="button";b.textContent=c;return b;}));}};
$("#chips").onclick=e=>{if(e.target.tagName=="BUTTON")ask(e.target.textContent)};
$("#f").onsubmit=e=>{e.preventDefault();ask(inp.value);inp.value=""};
$("#toWA").onclick=e=>{e.preventDefault();window.open(wa("Halo Samudra Detailing, saya lanjut dari chat website:\n"+(hist.slice(-6).join("\n")||"Saya ingin tanya paket detailing.")+"\nPaket terpilih: "+sv().n+" ("+Z[zi].n+")"),"_blank","noopener,noreferrer")};
</script>
</body>
</html>
